//! The bundled species-name table is what `data/l18n/README.md` and
//! `data/l18n/SOURCES.tsv` say it is.
//!
//! The table is data generated by `scripts/build-species-names.py` from files
//! this repository does not hold, so nothing in the build can re-derive it. What
//! can be checked is that the three things that describe it agree: the table, the
//! per-source counts the generator wrote beside it, and the coverage figures the
//! README quotes. Each is counted here independently of the loader, and the
//! loader is then held to the same counts, so a parser that dropped a column or
//! shifted one cell would be caught by the disagreement and not by a spot check.

use std::collections::BTreeMap;

use birdnet_core::i18n::{ENGLISH, LANGUAGES, LanguagePack};

const TABLE: &str = include_str!("../data/l18n/species_names.tsv");
const SOURCES: &str = include_str!("../data/l18n/SOURCES.tsv");
const README: &str = include_str!("../data/l18n/README.md");

/// How many species every source file lists. Upstream pads each language to the
/// same set, so this is also the denominator of a language's coverage.
const SPECIES_IN_EACH_SOURCE: u32 = 7058;

fn header() -> Vec<&'static str> {
    TABLE.lines().next().unwrap().split('\t').collect()
}

fn rows() -> impl Iterator<Item = Vec<&'static str>> {
    TABLE.lines().skip(1).map(|l| l.split('\t').collect())
}

/// Names per language code, counted straight from the table text.
fn counted() -> BTreeMap<&'static str, usize> {
    let codes = header();
    let mut out: BTreeMap<&str, usize> = codes[1..].iter().map(|c| (*c, 0)).collect();
    for row in rows() {
        for (code, cell) in codes[1..].iter().zip(&row[1..]) {
            if !cell.is_empty() {
                *out.get_mut(code).unwrap() += 1;
            }
        }
    }
    out
}

fn non_english_codes() -> Vec<&'static str> {
    LANGUAGES
        .iter()
        .map(|l| l.code)
        .filter(|c| *c != ENGLISH)
        .collect()
}

#[test]
fn the_table_has_a_column_for_every_language_but_english_and_nothing_else() {
    let mut expected = vec!["sci_name"];
    expected.extend(non_english_codes());
    assert_eq!(header(), expected);
}

#[test]
fn every_row_is_whole_and_the_keys_are_sorted_and_unique() {
    let width = header().len();
    let mut last: Option<&str> = None;
    for (n, row) in rows().enumerate() {
        assert_eq!(row.len(), width, "row {}: {:?}", n + 2, row.first());
        let key = row[0];
        assert!(
            !key.is_empty() && key == key.trim(),
            "row {}: key {key:?}",
            n + 2
        );
        if let Some(prev) = last {
            assert!(prev.as_bytes() < key.as_bytes(), "{prev:?} then {key:?}");
        }
        last = Some(key);
    }
    assert!(TABLE.ends_with('\n') && !TABLE.contains('\r'));
}

#[test]
fn a_row_exists_only_for_a_species_with_a_name_and_no_cell_needs_trimming() {
    for (n, row) in rows().enumerate() {
        assert!(
            row[1..].iter().any(|c| !c.is_empty()),
            "row {} ({}) has no translation at all",
            n + 2,
            row[0]
        );
        for cell in &row[1..] {
            assert_eq!(*cell, cell.trim(), "row {} ({})", n + 2, row[0]);
        }
    }
}

/// `code -> (sha256, names)` from `SOURCES.tsv`.
fn sources() -> BTreeMap<&'static str, (&'static str, usize)> {
    let mut lines = SOURCES.lines();
    assert_eq!(lines.next(), Some("code\tsha256\tnames"));
    lines
        .map(|l| {
            let mut f = l.split('\t');
            let (code, sha, names) = (f.next().unwrap(), f.next().unwrap(), f.next().unwrap());
            assert!(f.next().is_none(), "{l:?}");
            (code, (sha, names.parse().unwrap()))
        })
        .collect()
}

#[test]
fn sources_lists_every_language_with_a_sha256_and_the_names_the_table_holds() {
    let sources = sources();
    let mut codes: Vec<&str> = LANGUAGES.iter().map(|l| l.code).collect();
    codes.sort_unstable();
    assert_eq!(sources.keys().copied().collect::<Vec<_>>(), codes);

    let counted = counted();
    for (code, (sha, names)) in &sources {
        assert!(
            sha.len() == 64
                && sha
                    .bytes()
                    .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
            "{code}: {sha:?} is not a lower-case sha256"
        );
        let in_table = counted.get(code).copied().unwrap_or(0);
        assert_eq!(*names, in_table, "{code}: SOURCES.tsv vs the table");
    }
}

#[test]
fn the_loader_reads_the_same_number_of_names_as_the_table_holds() {
    let counted = counted();
    for code in non_english_codes() {
        let pack = LanguagePack::bundled(code).unwrap();
        assert_eq!(pack.species_count(), counted[code], "{code}");
    }
    assert_eq!(LanguagePack::bundled(ENGLISH).unwrap().species_count(), 0);
}

#[test]
fn the_loader_puts_each_name_with_its_own_species() {
    // Independent of how the loader indexes columns: take the cells straight from
    // the text for a spread of columns, first, middle and last included.
    let codes = header();
    let probes = [
        codes[1],
        codes[codes.len() / 2],
        codes[codes.len() - 1],
        "de",
        "ja",
    ];
    for code in probes {
        let col = codes.iter().position(|c| *c == code).unwrap();
        let pack = LanguagePack::bundled(code).unwrap();
        let mut checked = 0;
        for row in rows().step_by(97) {
            if !row[col].is_empty() {
                assert_eq!(pack.translate(row[0]), row[col], "{code} {}", row[0]);
                checked += 1;
            }
        }
        assert!(checked > 0, "{code}: the probe never found a name");
    }
}

/// `(code, names, percent)` from the README's coverage table.
fn readme_coverage() -> Vec<(String, usize, String)> {
    README
        .lines()
        .filter_map(|l| {
            let cells: Vec<&str> = l
                .trim()
                .trim_matches('|')
                .split('|')
                .map(str::trim)
                .collect();
            let [_, code, names, pct] = cells[..] else {
                return None;
            };
            let code = code.strip_prefix('`')?.strip_suffix('`')?;
            let names = names.replace(',', "").parse().ok()?;
            Some((code.to_owned(), names, pct.to_owned()))
        })
        .collect()
}

#[test]
fn the_readme_quotes_the_coverage_the_table_has() {
    let quoted = readme_coverage();
    let counted = counted();
    assert_eq!(
        quoted.iter().map(|(c, ..)| c.as_str()).collect::<Vec<_>>(),
        non_english_codes(),
        "the README table must list every language but English, in code order"
    );
    for (code, names, pct) in quoted {
        assert_eq!(names, counted[code.as_str()], "{code}: the README count");
        // One decimal place, rounded half up, in integer arithmetic.
        let tenths = (u32::try_from(names).unwrap() * 1000 + SPECIES_IN_EACH_SOURCE / 2)
            / SPECIES_IN_EACH_SOURCE;
        assert_eq!(
            pct,
            format!("{}.{}%", tenths / 10, tenths % 10),
            "{code}: the README share"
        );
    }
}
